\[
\overline n_\alpha
=\frac{1}{\beta}\frac{\partial\ln\Xi_\alpha}{\partial\mu}
=\frac{1}{e^{\beta(\epsilon_\alpha-\mu)}+1}
\equiv f_{\mathrm{FD}}(\epsilon_\alpha).
\tag*{[2]}
\]
